def comps(mask):
    seen=set(); n=0
    for cell in mask:
        if cell in seen: continue
        n+=1; st=[cell]
        while st:
            r,c=st.pop()
            if (r,c) in seen: continue
            seen.add((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    if dr==0 and dc==0: continue
                    q=(r+dr,c+dc)
                    if q in mask and q not in seen: st.append(q)
    return n

